<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialDeviceNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialDeviceNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withDeviceName,
 * getDeviceName/deviceName accessors, and isDeviceNameChanged with/without original.
 */
class UserWebauthnCredentialDeviceNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDeviceName creates a new instance with the DeviceName set
     * from a string value, and getDeviceName returns the primitive string.
     */
    public function testWithDeviceNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialDeviceNameAccessorUnitTest();

        // Act
        $result = $holder->withDeviceName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDeviceName());
    }
    /**
     * Asserts that withdeviceName has access to the value object
     * from a string value, and getDeviceName returns the primitive string.
     */
    public function testWithDeviceNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialDeviceNameAccessorUnitTest();

        // Act
        $result = $holder->withDeviceName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->deviceName()->value());
    }
    public function testChangedDeviceName(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialDeviceNameAccessorUnitTest();
        $original = $holder->withDeviceName('one');
        $same = $holder->withDeviceName('one');
        $modified = $holder->withDeviceName('other');

        // Act
        $unchanged = $holder->isDeviceNameChanged();
        $withSame = $original->isDeviceNameChanged($same);
        $withDiferent = $original->isDeviceNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialDeviceNameAccessorUnitTest
{
    use UserWebauthnCredentialDeviceNameAccessor;
}
